// CR-03 (CZ-33) — Stock Entry Downtime UI glue. Ships via fixtures as a
// Client Script (file-backed doctype_js silently fails on FC workers).
// Mirrors the authoritative server pass in cr03_downtime.validate_downtime.
//   CL-07  duration = to_time - from_time in the header Downtime UOM
//   CL-08  custom_downtime = sum of row durations when rows exist
//   CL-09  custom_net_run_time = production_time - downtime (never < 0)
// Read-only behaviour is declarative (read_only_depends_on on the
// fields), so this script only computes values. All set_value calls are
// equality-guarded to avoid a dirty/refresh loop.

function _cr03_to_minutes(val, uom) {
    val = flt(val);
    return (uom === "Minutes") ? val : val * 60.0;
}

function _cr03_recompute_net(frm) {
    const pt_uom = frm.doc.custom_time_uom || "Hours";
    const dt_uom = frm.doc.custom_downtime_uom || "Hours";
    const pt_min = _cr03_to_minutes(frm.doc.custom_production_time, pt_uom);
    const dt_min = _cr03_to_minutes(frm.doc.custom_downtime, dt_uom);
    let net_min = pt_min - dt_min;
    if (net_min < 0) net_min = 0; // CL-09 — never below zero
    const net = (pt_uom === "Minutes") ? net_min : net_min / 60.0;
    if (flt(frm.doc.custom_net_run_time) !== flt(net)) {
        frm.set_value("custom_net_run_time", net);
    }
}

function _cr03_rollup_downtime(frm) {
    const rows = frm.doc.custom_downtime_details || [];
    if (rows.length) {
        let total = 0;
        rows.forEach((r) => { total += flt(r.duration); });
        if (flt(frm.doc.custom_downtime) !== flt(total)) {
            frm.set_value("custom_downtime", total); // fires custom_downtime -> net
        } else {
            _cr03_recompute_net(frm);
        }
    } else {
        _cr03_recompute_net(frm);
    }
}

function _cr03_row_duration(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row.from_time || !row.to_time) { return; } // manual duration kept
    const uom = frm.doc.custom_downtime_uom || "Hours";
    const secs = moment(row.to_time).diff(moment(row.from_time), "seconds");
    if (secs <= 0) {
        frappe.msgprint(__("Row #{0}: To Time must be later than From Time.", [row.idx]));
        return;
    }
    const dur = (uom === "Minutes") ? secs / 60.0 : secs / 3600.0;
    frappe.model.set_value(cdt, cdn, "duration", dur); // fires duration -> rollup
}

frappe.ui.form.on("Stock Entry", {
    custom_production_time(frm) { _cr03_recompute_net(frm); },
    custom_time_uom(frm) { _cr03_recompute_net(frm); },
    custom_downtime(frm) { _cr03_recompute_net(frm); },
    custom_downtime_uom(frm) { _cr03_rollup_downtime(frm); },
    custom_downtime_details_add(frm) { _cr03_rollup_downtime(frm); },
    custom_downtime_details_remove(frm) { _cr03_rollup_downtime(frm); },
    validate(frm) { _cr03_rollup_downtime(frm); },
});

frappe.ui.form.on("Production Downtime Detail", {
    from_time(frm, cdt, cdn) { _cr03_row_duration(frm, cdt, cdn); },
    to_time(frm, cdt, cdn) { _cr03_row_duration(frm, cdt, cdn); },
    duration(frm) { _cr03_rollup_downtime(frm); },
});

