function apply_field_visibility(frm) {
    hide_loan_terms_section(frm);        // CR-02
    hide_means_of_finance_section(frm);  // CR-03
    hide_result_tab(frm);                 // CR-05
}

// ============================================================
// CR-02: Hide Loan Terms section on CAPEX tab
// ============================================================
function hide_loan_terms_section(frm) {
    // Hide the section break — collapses everything under it
    frm.set_df_property('sec_loan_terms', 'hidden', 1);

    // Belt-and-braces: hide each child field too
    const loan_terms_fields = [
        'loan_tenure_years',
        'interest_rate_tl',
        'interest_rate_reduction',
        'moratorium_years',
        'working_capital_amount',
        'interest_rate_wc',
        'interest_on_wc_annual',
        // OPEX-side duplicates of the same loan-term concepts
        'custom_opex_working_capital',
        'custom_opex_interest_rate_wc',
        'custom_opex_interest_on_wc_annual',
        'custom_opex_moratorium_years'
    ];

    loan_terms_fields.forEach(fieldname => {
        frm.set_df_property(fieldname, 'hidden', 1);
    });
}

// ============================================================
// CR-03: Hide Means of Finance section on CAPEX tab
// ============================================================
function hide_means_of_finance_section(frm) {
    // Hide the section break
    frm.set_df_property('sec_means_of_finance', 'hidden', 1);

    // Belt-and-braces: hide each child field too
    const means_of_finance_fields = [
        'equity_amount',
        'equity_percent',
        'loan_amount',
        'loan_percent'
    ];

    means_of_finance_fields.forEach(fieldname => {
        frm.set_df_property(fieldname, 'hidden', 1);
    });
}

// ============================================================
// CR-05: Hide entire RESULT tab
// ============================================================
function hide_result_tab(frm) {
    // Preferred approach — hide the Tab Break, collapses the whole tab
    frm.set_df_property('custom_result', 'hidden', 1);

    // Belt-and-braces: hide each field inside in case Tab Break hide doesn't fully cascade
    const result_fields = [
        // Profitability Summary (Year 1 Base)
        'ebitda',
        'ebitda_percent',
        'gross_profit',
        'gross_profit_percent',
        'depreciation_annual',
        'interest_annual',
        'ebit',
        'pbt',
        'tax_rate',
        'pat',
        'pat_percent',
        // Key Performance Indicators
        'project_irr',
        'equity_irr',
        'npv',
        'discount_rate',
        'terminal_growth_rate',
        'payback_period_years',
        'avg_dscr',
        'min_dscr',
        'terminal_value',
        // WBS / Sub-WBS Status
        'wbs_status',
        'sub_wbs_status'
    ];

    result_fields.forEach(fieldname => {
        frm.set_df_property(fieldname, 'hidden', 1);
    });
}



function hide_result_tab_label(frm) {
    setTimeout(function() {
        // Target the tab nav item directly by ID
        $('#financial-model-custom_result-tab').closest('li').hide();

        // Belt-and-braces: also hide the anchor itself in case closest('li') misses
        $('#financial-model-custom_result-tab').hide();

        // If user landed on RESULT tab, bounce them to Details
        const active_tab_id = $('.form-tabs li.active a').attr('id') || '';
        if (active_tab_id.includes('custom_result')) {
            $('.form-tabs li:visible:first a').click();
        }
    }, 100);
}

frappe.ui.form.on('Sub WBS Element', {
    after_save: function(frm) {

        // If name changed (rename happened)
        if (!frm.is_new() && frm.doc.name && frm.doc.name.startsWith("SUB ")) {

            // Reload correct document
            frappe.set_route('Form', 'Sub WBS Element', frm.doc.name);

        } else {

            // fallback refresh
            setTimeout(() => {
                frm.reload_doc();
            }, 500);

        }
    }
});

frappe.ui.form.on('Sub WBS Element', {
    after_save: function(frm) {
        if (!frm.is_new() && frm.doc.name && frm.doc.name.startsWith("SUB WBS-")) {
            frappe.set_route('Form', 'Sub WBS Element', frm.doc.name);
        } else {
            setTimeout(() => frm.reload_doc(), 500);
        }
    }
});

frappe.ui.form.on('Sub WBS Element', {
    refresh(frm) {
        if (frm.is_new()) return;
        frm.add_custom_button(__('Refresh Spent'), () => {
            frappe.call({
                method: 'refresh_sub_wbs_spent',
                args: { sub_wbs: frm.doc.name },
                freeze: true,
                freeze_message: __('Recalculating spent & utilization...'),
                callback(r) {
                    if (r.message) {
                        frappe.show_alert({
                            message: __('Spent: {0} | Utilization: {1}%', [
                                format_currency(r.message.spent),
                                Math.round(r.message.utilization * 100) / 100
                            ]),
                            indicator: 'green'
                        });
                        frm.reload_doc();
                    }
                }
            });
        });
    }
});
